import"./chunks/assets.CDWaORDm.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"SDD-RIPER-ONE 简单使用感受","description":"","frontmatter":{"title":"SDD-RIPER-ONE 简单使用感受"},"headers":[],"relativePath":"blog/posts/5456.md","filePath":"blog/posts/5456.md","lastUpdated":1783382106000}`),a={name:`blog/posts/5456.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="sdd-riper-one-简单使用感受" tabindex="-1">SDD-RIPER-ONE 简单使用感受 <a class="header-anchor" href="#sdd-riper-one-简单使用感受" aria-label="Permalink to “SDD-RIPER-ONE 简单使用感受”">​</a></h1><img class="telegram-media" src="/telegram/AQADLw9rG_mlSFd9.jpg" alt="Telegram 图片" loading="lazy" decoding="async"><div class="telegram-content"><u>SDD-RIPER-ONE 简单使用感受</u><br><br><a href="https://t.me/zhetengsha/5451">介绍帖</a><br><br>简单用了一段时间 主要产出了一个 <a href="/blog/posts/5454"><u>快捷指令: GitHub Uploader</u></a><br><br>▎标准流程<br><code>create_codemap</code> (生成代码索引地图) -&gt; <code>build_context_bundle</code> (整理需求上下文) -&gt; <code>sdd_bootstrap</code> 这里如图说需求开始<br><br>下面是自动的<br><br> -&gt; <code>Research</code> -&gt; (<code>Innovate</code>, 可选) -&gt; <code>Plan</code> -&gt; <code>Execute</code> -&gt; <code>Review</code><br><br>手动 <code>archive</code> 归档沉淀<br><br>首次执行计划 和 <code>review_execute</code> 之后修改了计划, 都需要手动 <code>Plan Approved</code> 确认执行<br><br>▎感受<br><br>官方没有跟 <a href="https://t.me/zhetengsha/5267">Compound Engineering</a> 一样的 Codex Prompts, 也没把 skills 拆出来. 当然你也可以自己生成 或者用任何快捷输入工具方便你每次调用...<br><br>review 的时候没有 <code>ce:review</code> 开好多个 subagent 从不同角度 review 来得爽 <img class="telegram-custom-emoji" src="/telegram/AgAD8hEAAvcHaFQ.webp" alt="😄" loading="lazy" decoding="async"><br>自带的只有 <code>review_spec</code> 和 <code>review_execute</code>, 其实感觉好像不如 <code>ce:review</code> 全面<br><br>有时候还感觉被 spec 束缚太死, 可能会出现顾头不顾腚的情况<br><br>生成的文档信息里可能包含隐私, 公开仓库感觉不太适合带着一起上传...<br><br>▎Codex App 中使用 SDD-RIPER 的最佳实践<br><br><a href="https://github.com/huisezhiyin/sdd-riper/issues/4">https://github.com/huisezhiyin/sdd-riper/issues/4</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/207/">AI 合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">合集</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭</a> <img class="telegram-custom-emoji" src="/telegram/AgADbg0AAgj82Vc.webp" alt="🥰" loading="lazy" decoding="async"><a href="https://t.me/xream_bot">联系推广</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #AI #AgenticCoding #AI #编程 #开发工作流 #工程协作 #Spec #驱动 #GitHub #Python</div><p class="telegram-source"><a href="https://t.me/zhetengsha/5456">查看 Telegram 原文</a></p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};